// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Login Sign in with username and password
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout End the current session
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// ListCollections A library's collections (F005 R23)
	// (GET /collections)
	ListCollections(w http.ResponseWriter, r *http.Request, params ListCollectionsParams)
	// GetCollection A collection with its movies, by release date (F005 R23)
	// (GET /collections/{collectionId})
	GetCollection(w http.ResponseWriter, r *http.Request, collectionId string)
	// BrowseFolders Sub-folders of a server folder, for the folder picker (admin)
	// (GET /fs/browse)
	BrowseFolders(w http.ResponseWriter, r *http.Request, params BrowseFoldersParams)
	// GetHealth Liveness and build info
	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// GetImage An artwork image, resized for the client (F005 R19)
	// (GET /images/{imageId})
	GetImage(w http.ResponseWriter, r *http.Request, imageId string, params GetImageParams)
	// GetItem An item with its files and streams
	// (GET /items/{itemId})
	GetItem(w http.ResponseWriter, r *http.Request, itemId string)
	// ListItemArtwork Artwork candidates (admin, F005 R30)
	// (GET /items/{itemId}/artwork)
	ListItemArtwork(w http.ResponseWriter, r *http.Request, itemId ItemId, params ListItemArtworkParams)
	// UnlockItemArtwork Back to the automatic choice (admin, F005 R30)
	// (DELETE /items/{itemId}/artwork/{kind})
	UnlockItemArtwork(w http.ResponseWriter, r *http.Request, itemId ItemId, kind ArtworkKind)
	// SelectItemArtwork Pick an image and lock the kind (admin, F005 R30)
	// (PUT /items/{itemId}/artwork/{kind})
	SelectItemArtwork(w http.ResponseWriter, r *http.Request, itemId ItemId, kind ArtworkKind)
	// UnmatchItem Forget a match; the item is matched again automatically (admin, F005 R26)
	// (DELETE /items/{itemId}/match)
	UnmatchItem(w http.ResponseWriter, r *http.Request, itemId ItemId)
	// MatchItem Fix an item's match (admin, F005 R26, R39)
	// (POST /items/{itemId}/match)
	MatchItem(w http.ResponseWriter, r *http.Request, itemId ItemId)
	// UpdateItemMetadata Edit and lock fields (admin, F005 R29)
	// (PATCH /items/{itemId}/metadata)
	UpdateItemMetadata(w http.ResponseWriter, r *http.Request, itemId ItemId)
	// StartPlayback Start playing a movie or an episode (F006 R1–R5)
	// (POST /items/{itemId}/playback)
	StartPlayback(w http.ResponseWriter, r *http.Request, itemId string)
	// RefreshItem Refresh an item's metadata now (admin, F005 R31)
	// (POST /items/{itemId}/refresh)
	RefreshItem(w http.ResponseWriter, r *http.Request, itemId ItemId)
	// MarkUnwatched Mark an item unwatched for the active profile; a show or season unmarks every episode (F006 R35)
	// (DELETE /items/{itemId}/watched)
	MarkUnwatched(w http.ResponseWriter, r *http.Request, itemId string)
	// MarkWatched Mark an item watched for the active profile; a show or season marks every episode (F006 R35)
	// (PUT /items/{itemId}/watched)
	MarkWatched(w http.ResponseWriter, r *http.Request, itemId string)
	// ListLibraries All libraries, with folder status, counts and scan state
	// (GET /libraries)
	ListLibraries(w http.ResponseWriter, r *http.Request)
	// CreateLibrary Create a library and start its first scan (admin)
	// (POST /libraries)
	CreateLibrary(w http.ResponseWriter, r *http.Request)
	// DeleteLibrary Delete a library's rows; files on disk are never touched (admin)
	// (DELETE /libraries/{libraryId})
	DeleteLibrary(w http.ResponseWriter, r *http.Request, libraryId LibraryId)
	// GetLibrary One library
	// (GET /libraries/{libraryId})
	GetLibrary(w http.ResponseWriter, r *http.Request, libraryId LibraryId)
	// UpdateLibrary Rename a library, change its folders or scan interval (admin)
	// (PATCH /libraries/{libraryId})
	UpdateLibrary(w http.ResponseWriter, r *http.Request, libraryId LibraryId)
	// ListLibraryItems Items of a library, by kind and parent
	// (GET /libraries/{libraryId}/items)
	ListLibraryItems(w http.ResponseWriter, r *http.Request, libraryId LibraryId, params ListLibraryItemsParams)
	// RefreshLibraryMetadata Refresh a library's metadata now (F005 R31)
	// (POST /libraries/{libraryId}/metadata/refresh)
	RefreshLibraryMetadata(w http.ResponseWriter, r *http.Request, libraryId LibraryId)
	// ListLibraryReview Items that need an admin's eye (F005 R5, R38)
	// (GET /libraries/{libraryId}/review)
	ListLibraryReview(w http.ResponseWriter, r *http.Request, libraryId LibraryId, params ListLibraryReviewParams)
	// GetLibraryScan Current scan progress (admin)
	// (GET /libraries/{libraryId}/scan)
	GetLibraryScan(w http.ResponseWriter, r *http.Request, libraryId LibraryId)
	// ScanLibrary Scan now, or full rescan (admin)
	// (POST /libraries/{libraryId}/scan)
	ScanLibrary(w http.ResponseWriter, r *http.Request, libraryId LibraryId)
	// GetLibraryScanEvents Live scan progress as server-sent events (admin)
	// (GET /libraries/{libraryId}/scan/events)
	GetLibraryScanEvents(w http.ResponseWriter, r *http.Request, libraryId LibraryId)
	// ListUnrecognizedFiles Files whose name couldn't be understood (admin)
	// (GET /libraries/{libraryId}/unrecognized)
	ListUnrecognizedFiles(w http.ResponseWriter, r *http.Request, libraryId LibraryId, params ListUnrecognizedFilesParams)
	// GetMe The signed-in account, its profiles and the active one
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// UpdateMe Update own display name or locale
	// (PATCH /me)
	UpdateMe(w http.ResponseWriter, r *http.Request)
	// ListContinueWatching In-progress movies and episodes, plus each show's next episode, most recent first (F006 R37)
	// (GET /me/continue-watching)
	ListContinueWatching(w http.ResponseWriter, r *http.Request, params ListContinueWatchingParams)
	// ChangeMyPassword Change own password
	// (POST /me/password)
	ChangeMyPassword(w http.ResponseWriter, r *http.Request)
	// ListMyProfiles Profiles of the account
	// (GET /me/profiles)
	ListMyProfiles(w http.ResponseWriter, r *http.Request)
	// CreateMyProfile Add a profile (8 at most)
	// (POST /me/profiles)
	CreateMyProfile(w http.ResponseWriter, r *http.Request)
	// DeleteMyProfile Delete a profile (not the last one)
	// (DELETE /me/profiles/{profileId})
	DeleteMyProfile(w http.ResponseWriter, r *http.Request, profileId ProfileId)
	// UpdateMyProfile Update a profile
	// (PATCH /me/profiles/{profileId})
	UpdateMyProfile(w http.ResponseWriter, r *http.Request, profileId ProfileId)
	// RevokeMyOtherSessions Sign out every other device
	// (DELETE /me/sessions)
	RevokeMyOtherSessions(w http.ResponseWriter, r *http.Request)
	// ListMySessions Signed-in devices of the account
	// (GET /me/sessions)
	ListMySessions(w http.ResponseWriter, r *http.Request)
	// RevokeMySession Sign out one device
	// (DELETE /me/sessions/{sessionId})
	RevokeMySession(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// IdentifyFile Say what an unrecognized file is (admin, F005 R28)
	// (POST /media-files/{fileId}/identify)
	IdentifyFile(w http.ResponseWriter, r *http.Request, fileId string)
	// GetCandidateImage A candidate's poster, through the server (admin, F005 R27)
	// (GET /metadata/candidate-images/{path})
	GetCandidateImage(w http.ResponseWriter, r *http.Request, path string)
	// SearchMetadata Search TMDB for a match (admin, F005 R27)
	// (GET /metadata/search)
	SearchMetadata(w http.ResponseWriter, r *http.Request, params SearchMetadataParams)
	// GetMetadataSettings Which provider keys are in use (admin, F005 R34)
	// (GET /metadata/settings)
	GetMetadataSettings(w http.ResponseWriter, r *http.Request)
	// UpdateMetadataSettings Save or clear provider keys (admin, F005 R34)
	// (PATCH /metadata/settings)
	UpdateMetadataSettings(w http.ResponseWriter, r *http.Request)
	// GetMetadataStatus Providers and per-library progress (admin, F005 R35)
	// (GET /metadata/status)
	GetMetadataStatus(w http.ResponseWriter, r *http.Request)
	// StartPairing Get a code to pair a TV
	// (POST /pairing)
	StartPairing(w http.ResponseWriter, r *http.Request)
	// ClaimPairing Sign a TV in with the code it shows
	// (POST /pairing/claim)
	ClaimPairing(w http.ResponseWriter, r *http.Request)
	// PollPairing Poll a pairing until it is claimed
	// (GET /pairing/{pairingId})
	PollPairing(w http.ResponseWriter, r *http.Request, pairingId string, params PollPairingParams)
	// GetPerson A person and what they're in, on this server (F005 R8)
	// (GET /people/{personId})
	GetPerson(w http.ResponseWriter, r *http.Request, personId string)
	// ListPlaybackSessions Every active playback session (admin, F006 R29)
	// (GET /playback)
	ListPlaybackSessions(w http.ResponseWriter, r *http.Request)
	// StopPlayback End a playback session (yours, or anyone's for an admin) and save its last position (F006 R8, R32)
	// (DELETE /playback/{sessionId})
	StopPlayback(w http.ResponseWriter, r *http.Request, sessionId PlaybackSessionId)
	// GetPlayback One of your playback sessions
	// (GET /playback/{sessionId})
	GetPlayback(w http.ResponseWriter, r *http.Request, sessionId PlaybackSessionId)
	// UpdatePlayback Change the audio track, subtitles, quality or bitrate of a session (F006 R6)
	// (PATCH /playback/{sessionId})
	UpdatePlayback(w http.ResponseWriter, r *http.Request, sessionId PlaybackSessionId)
	// ReportPlaybackProgress Report the position and state; also keeps the session alive (F006 R32)
	// (POST /playback/{sessionId}/progress)
	ReportPlaybackProgress(w http.ResponseWriter, r *http.Request, sessionId PlaybackSessionId)
	// GetServerInfo Identify a PLAID server
	// (GET /server)
	GetServerInfo(w http.ResponseWriter, r *http.Request)
	// GetServerCapabilities ffprobe and file watching status (admin)
	// (GET /server/capabilities)
	GetServerCapabilities(w http.ResponseWriter, r *http.Request)
	// SelectProfile Set the active profile of the current session
	// (POST /session/profile)
	SelectProfile(w http.ResponseWriter, r *http.Request)
	// GetPlaybackSettings Playback settings (admin, F006 R30)
	// (GET /settings/playback)
	GetPlaybackSettings(w http.ResponseWriter, r *http.Request)
	// UpdatePlaybackSettings Change playback settings (admin, F006 R30)
	// (PATCH /settings/playback)
	UpdatePlaybackSettings(w http.ResponseWriter, r *http.Request)
	// GetSetup First-run setup state
	// (GET /setup)
	GetSetup(w http.ResponseWriter, r *http.Request)
	// CreateFirstAdmin Create the first admin account and sign in
	// (POST /setup/admin)
	CreateFirstAdmin(w http.ResponseWriter, r *http.Request)
	// ListUsers All accounts (admin)
	// (GET /users)
	ListUsers(w http.ResponseWriter, r *http.Request)
	// CreateUser Create an account with a temporary password (admin)
	// (POST /users)
	CreateUser(w http.ResponseWriter, r *http.Request)
	// DeleteUser Delete an account, its profiles and sessions (admin)
	// (DELETE /users/{userId})
	DeleteUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// UpdateUser Update an account (admin)
	// (PATCH /users/{userId})
	UpdateUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// ResetUserPassword Set a temporary password (admin)
	// (POST /users/{userId}/password)
	ResetUserPassword(w http.ResponseWriter, r *http.Request, userId UserId)
	// ListUserSessions Signed-in devices of an account (admin)
	// (GET /users/{userId}/sessions)
	ListUserSessions(w http.ResponseWriter, r *http.Request, userId UserId)
	// RevokeUserSession Sign out one device of an account (admin)
	// (DELETE /users/{userId}/sessions/{sessionId})
	RevokeUserSession(w http.ResponseWriter, r *http.Request, userId UserId, sessionId SessionId)
}

